public class InnerBucketJournalTableConfigurationFactory(Action<Humidifier.S3.BucketTypes.JournalTableConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.S3.BucketTypes.JournalTableConfiguration>
{

    internal InnerBucketMetadataTableEncryptionConfigurationFactory EncryptionConfigurationFactory { get; set; }

    internal InnerBucketRecordExpirationFactory RecordExpirationFactory { get; set; }

    protected override Humidifier.S3.BucketTypes.JournalTableConfiguration Create()
    {
        var journalTableConfigurationResult = CreateJournalTableConfiguration();
        factoryAction?.Invoke(journalTableConfigurationResult);

        return journalTableConfigurationResult;
    }

    private Humidifier.S3.BucketTypes.JournalTableConfiguration CreateJournalTableConfiguration()
    {
        var journalTableConfigurationResult = new Humidifier.S3.BucketTypes.JournalTableConfiguration();

        return journalTableConfigurationResult;
    }
    public override void CreateChildren(Humidifier.S3.BucketTypes.JournalTableConfiguration result)
    {
        base.CreateChildren(result);

        result.EncryptionConfiguration ??= EncryptionConfigurationFactory?.Build();
        result.RecordExpiration ??= RecordExpirationFactory?.Build();
    }

} // End Of Class

